<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Workspace · Spare</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="workspace"><header class="workspace-header"><a class="brand" href="<?= e(url('/dashboard')) ?>"><span class="brand-mark">s.</span> spare</a><div class="account"><span><?= e($user['name']) ?> · <?= e($role) ?></span><form method="post" action="<?= e(url('/logout')) ?>"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><button class="secondary">Sign out</button></form></div></header><main class="workspace-main"><span class="eyebrow">YOUR WORKSPACE</span><h1>Hello, <?= e($user['name']) ?>.</h1><p class="muted">Your account is ready. This is the foundation for your shop workspace.</p>
<?php if ($notice): ?><p class="notice" role="status"><?= e($notice) ?></p><?php endif; ?><?php if ($message): ?><p class="alert" role="alert"><?= e($message) ?></p><?php endif; ?>
<section class="panel"><h2>Your access</h2><p class="muted"><?= $user['role'] === 'superadmin' ? 'Platform administrator access. Shop management modules will be added next.' : ($user['role'] === 'shop_owner' ? 'You manage your shop and decide what your staff can access.' : 'Your shop owner manages these permissions. Modules will be added next.') ?></p><div class="permission-tags"><?php foreach (permissions() as $key => $label): if (can($user, $key)): ?><span><?= e($label) ?></span><?php endif; endforeach; ?></div><?php if ($user['role'] === 'staff'): ?><p class="muted">If you need additional access, contact your shop owner.</p><?php endif; ?></section>
<?php if ($user['role'] === 'shop_owner'): ?><section class="panel"><h2>Staff permissions</h2><p class="muted">Changes take effect immediately. Staff can only access permissions you enable.</p><?php if (!$staff): ?><p>No staff accounts yet. Use the account setup command to add your team.</p><?php endif; ?><?php foreach ($staff as $member): $granted = $member['permissions']; ?><form method="post" action="<?= e(url('/staff/permissions')) ?>" class="staff-form"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="staff_id" value="<?= (int)$member['id'] ?>"><h3><?= e($member['name']) ?></h3><p class="muted"><?= e($member['email']) ?></p><div class="checks"><?php foreach (permissions() as $key => $label): ?><label><input type="checkbox" name="permissions[]" value="<?= e($key) ?>" <?= in_array($key, $granted, true) ? 'checked' : '' ?>> <?= e($label) ?></label><?php endforeach; ?></div><button class="secondary">Save permissions</button></form><?php endforeach; ?></section><?php endif; ?></main></body></html>
